/**
 * 페이지 시각 효과 튜닝
 * ─────────────────────────────────────────────────────────
 * 이 파일만 수정하면 청첩장의 배경 효과가 즉시 바뀝니다.
 * 변경 후 저장 → 브라우저 새로고침으로 확인.
 */
export const effectsConfig = {
  // ─────────────────────────────────────────────────────────
  // 떠다니는 구름 효과 (배경 길상문 구름)
  // ─────────────────────────────────────────────────────────
  clouds: {
    // 켜기/끄기
    enabled: true,

    // 📌 구름 개수 결정 방식
    //   - count 가 숫자면 그 개수로 고정 (페이지 길이와 무관)
    //   - count 가 null 이면 density × 페이지수 만큼 자동
    //     (페이지가 길수록 구름이 더 많이 생겨 빈 공간 없이 채워줌)
    count: null,
    density: 7,             // 한 화면(=100vh) 당 구름 몇 개 (1~8 권장)

    // 📏 세로 간격
    // verticalJitter: 균등 분포에서 ±% 만큼 흔들기 (0 = 완벽한 등간격, 50 = 자유분방)
    verticalJitter: 45,

    // 📐 구름 크기 (px) — 이 범위에서 랜덤
    sizeMin: 75,
    sizeMax: 170,

    // 🕐 한 번 가로지르는 데 걸리는 시간 (초)
    //   값이 작을수록 빠릅니다. 너무 빠르면 산만하므로 60~120 권장
    speedMin: 95,
    speedMax: 115,

    // 🌊 위아래 흔들림 (px) — 둥둥 떠다니는 듯한 출렁임
    //   가로 흐름과 분리된 독립 애니메이션이라 값이 그대로 진폭이 됩니다.
    //   0 이면 일직선, 18~35 정도면 부드럽게 둥실둥실
    swayAmount: 28,

    // 🕐 위아래 한 번 출렁이는 주기 (초) — 이 범위에서 랜덤
    //   값이 작을수록 빠르게 까딱이고, 클수록 느긋하게 둥실거립니다.
    bobDurationMin: 4,
    bobDurationMax: 8,

    // 🌫️ 투명도 — 너무 진하면 본문 가독성이 떨어집니다 (0.04~0.15 권장)
    opacityMin: 0.05,
    opacityMax: 0.12,

    // ➡️ 좌·우 방향 비율 (1 = 모두 오른쪽, 0 = 모두 왼쪽, 0.5 = 반반)
    rightwardRatio: 0.5,

    // ☁️ 사용할 구름 종류 (invitation.js 의 ornaments 키)
    variants: ['cloud1', 'cloud2', 'cloud3'],
  },

  // ─────────────────────────────────────────────────────────
  // 전통 일러스트 (가마 + 말 탄 신랑 행렬)
  // — Hero 섹션 하단에 표시되는 가마/말 이미지의 크기·간격·투명도
  // ─────────────────────────────────────────────────────────
  procession: {
    // 켜기/끄기 (false 면 가마+말 행렬 자체를 숨김)
    enabled: true,

    // 📐 각 이미지의 최대 너비 (px)
    //   - 두 이미지의 균형을 맞추고 싶다면 동일 값으로
    //   - 말 이미지가 시각적으로 크게 보인다면 horseRiderWidth 를 작게
    palanquinWidth: 125,    // 가마(사인교)
    horseRiderWidth: 95,    // 말 탄 신랑

    // ↔️ 두 이미지 사이 간격 (px)
    gap: 19,

    // 🌫️ 전체 투명도 (0~1)
    //   - 1 이면 진하게, 0.6~0.8 이면 본문과 잘 어울리는 톤다운
    opacity: 0.77,
  },
}
